<?php
declare(strict_types=1);
require __DIR__.'/industry.php';

use App\Services\{CareService,PatientSummaryService,IndicatorService,Crypto};

$summaryService = new PatientSummaryService(new CareService($s,$doctor));
$emptyPatient = $s->insert('patients',['company_id'=>1,'name'=>'Sem histórico fictício']);
$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$emptyPatient,'team_id'=>1]);
$empty = $summaryService->summarize($emptyPatient);
verify($empty['plans']['total']===0 && $empty['plans']['focus']===null, 'Empty summary has no invented plan');
verify($empty['last_attended']===null && $empty['next_appointment']===null && $empty['latest_evolution']===null, 'Empty summary does not infer visits or evolution');
verify($empty['goals']['total']===0 && $empty['indicators']['items']===[], 'Empty summary does not invent clinical values');
foreach([$navigator,$manager,$admin,$worker,$dependent] as $actor) denied(fn()=>(new PatientSummaryService(new CareService($s,$actor)))->summarize(1),403);
denied(fn()=>(new PatientSummaryService(new CareService($s,$s->one('SELECT * FROM users WHERE id=7'))))->summarize(1),404);
denied(fn()=>$summaryService->summarize(2),404);
$s->execute('UPDATE care_team_assignments SET active=0 WHERE patient_id=1');
denied(fn()=>$summaryService->summarize(1),404);
$s->execute('UPDATE care_team_assignments SET active=1 WHERE patient_id=1');

$clinical = new CareService($s,$doctor);
$early = $clinical->create(array_replace($data,['start_date'=>date('Y-m-d',time()-7*86400),'reassessment_date'=>date('Y-m-d',time()-86400),'clinical_notes'=>'Observação restrita para leitura rápida.','status'=>'active']))['id'];
$clinical->create(array_replace($data,['reassessment_date'=>date('Y-m-d',time()+7*86400),'status'=>'active']));
$clinical->create(array_replace($data,['status'=>'closed']));
$engine = new IndicatorService($clinical);
$latestMeasurement = $engine->measure($indicator,['value'=>0,'source'=>'professional','collected_at'=>date('Y-m-d H:i:s'),'method'=>'Medição profissional fictícia'])['id'];
$engine->measure($indicator,['value'=>3,'source'=>'self_reported','collected_at'=>date('Y-m-d H:i:s'),'method'=>'Autorrelato fictício']);
$engine->measure($indicator,['value'=>99,'source'=>'professional','collected_at'=>date('Y-m-d H:i:s',time()-7200),'method'=>'Coleta antiga registrada depois']);
$unmeasured = $engine->create(['patient_id'=>1,'name'=>'Indicador sem coleta','type'=>'numeric','unit'=>'unidade','measurement_method'=>'Teste','frequency'=>'Pactuada'])['id'];
$clinical->evolution($plan,['kind'=>'clinical','notes'=>'Evolução médica fictícia.']);
(new CareService($s,$nurse))->evolution($plan,['kind'=>'nursing','notes'=>'Registro de enfermagem fictício, com autoria preservada.']);
$s->insert('clinical_evolutions',['plan_id'=>$early,'author_id'=>1,'kind'=>'clinical','notes'=>Crypto::encrypt('Registro mais antigo inserido depois.'),'created_at'=>date('Y-m-d H:i:s',time()-86400)]);
$lastAttended = $s->insert('appointments',['company_id'=>1,'patient_id'=>1,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()-86400),'status'=>'attended']);
$s->insert('appointments',['company_id'=>1,'patient_id'=>1,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()-60),'status'=>'expected']);
$s->insert('appointments',['company_id'=>1,'patient_id'=>1,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+86400),'status'=>'attended']);
$nextAppointment = $s->insert('appointments',['company_id'=>1,'patient_id'=>1,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+300),'status'=>'expected']);
$continuity->referral(['patient_id'=>1,'team_id'=>1,'to_professional_id'=>2,'reason'=>'Motivo fictício restrito ao profissional habilitado.']);
$snapshot = $summaryService->summarize(1);
verify($snapshot['patient']['id']===1 && $snapshot['patient']['name']==='Linked','Summary tied to exact patient');
verify($snapshot['plans']['active']===2 && $snapshot['plans']['focus']['id']===$early,'Focus is active plan with nearest reassessment, not newest closed plan');
verify($snapshot['plans']['focus']['clinical_notes']==='Observação restrita para leitura rápida.','Authorized summary decrypts the original note');
verify($snapshot['reassessment']['overdue']===true,'Overdue refers only to the planned date');
verify((int)$snapshot['last_attended']['id']===$lastAttended,'Only past attended visits count as attendance');
verify((int)$snapshot['next_appointment']['id']===$nextAppointment,'Nearest expected or confirmed future visit selected');
verify($snapshot['latest_evolution']['notes']==='Registro de enfermagem fictício, com autoria preservada.' && $snapshot['latest_evolution']['author_name']===$nurse['name'],'Latest evolution ordered by date then id with original text and author');
verify($snapshot['latest_review']['notes']==='Revisão humana','Latest review retains recorded text');
verify($snapshot['recent_referrals'][0]['reason']==='Motivo fictício restrito ao profissional habilitado.','Referral reason remains restricted and exact');
$reading = array_values(array_filter($snapshot['indicators']['items'],fn($i)=>(int)$i['id']===$indicator))[0];
verify((float)$reading['professional']['value_num']===0.0 && (float)$reading['self_reported']['value_num']===3.0,'Professional and self-reported values never merged; zero is a valid measurement');
verify((int)$reading['professional']['id']===$latestMeasurement,'Latest collected value selected, not latest inserted value');
verify($reading['self_reported']['professional_name']===null && $reading['self_reported']['recorded_by_name']===$doctor['name'],'Self-report origin and recorder clearly separated');
verify(count($snapshot['indicators']['items'])===6 && $snapshot['indicators']['total']===7,'Visible indicator limit reports full total');
$noData = array_values(array_filter($snapshot['indicators']['items'],fn($i)=>(int)$i['id']===$unmeasured))[0];
verify($noData['professional']===null && $noData['self_reported']===null,'Indicator without collection stays without value');
$pendingGoal = array_values(array_filter($snapshot['goals']['items'],fn($g)=>(int)$g['id']===$goal))[0];
verify($pendingGoal['progress']['state']==='insufficient_data','Summary uses the original minimum-evidence rule');
verify($s->one('SELECT id FROM audit_logs WHERE event=? AND resource_type=? AND resource_id=?',['patient_summary_read','patient',1])!==null,'Summary access audited');
$nursingSummary=(new PatientSummaryService(new CareService($s,$nurse)))->summarize(1);
verify($nursingSummary['patient']['id']===1,'Linked nurse can read the same clinical summary');
echo "OK: {$count} combined summary/domain checks\n";
